---GetIOSQuality
---获取ios设备的图像品质
function MobileHardwareUtils.GetIOSQuality()
    local deviceModel = SystemInfo.deviceModel
    if string.isEmpty(deviceModel) then
        return GraphicQuality.High ---
    end
    ---@type TableML.TableFile
    local tableFile = SettingModule.Get(IosModel_Setting_Path)
    ---@type TableML.TableFileRow
    local row = tableFile:GetByPrimaryKey(deviceModel, false)
    if isNull(row) then
        return GraphicQuality.High
    end
    return checkNumber(row:Get("quality"))
end

---SetRenderScale
---设置渲染分辨率
function MobileHardwareUtils.SetRenderScale(sceneHeight)
    local universalRenderPipelineAsset = CS.UnityEngine.Rendering.Universal.UniversalRenderPipeline.asset

    --避免高分辨率的手机以超过1K的分辨率去渲染
    local baseScale = 1
    if screenHeight > 1200 then --1200 * 0.9 = 1080
        ---长宽高比例小于1.5的，被认为是pad类型
        ---iphone也不限制最高1080
        if screenWidth / screenHeight < 1.5 or Application.platform == RuntimePlatform.IPhonePlayer then
            baseScale = screenHeight / 1200
        end
    end

    if Application.platform == RuntimePlatform.WindowsPlayer or Application.platform == RuntimePlatform.WindowsEditor or Application.platform == RuntimePlatform.OSXEditor then
        universalRenderPipelineAsset.renderScale = 1
    else
        -- local _screenHeight = math.max(screenHeight, 1080) --避免低于1080分辨率的设备出错
        local newScale = math.min(sceneHeight / screenHeight, 0.9) --避免低于1080分辨率的设置的scale过高

        universalRenderPipelineAsset.renderScale = newScale * baseScale
    end
end

---SetDRSScale
---设置场景的动态分辨率scale的值
---@param scale number
function MobileHardwareUtils.SetDRSScale(scale)
    scale = math.max(scale, MIN_SCALE)
    local universalRenderPipelineAsset = CS.UnityEngine.Rendering.Universal.UniversalRenderPipeline.asset
    -- universalRenderPipelineAsset.renderScale = 1 --此值固定为1

    --避免高分辨率的手机以超过1K的分辨率去渲染
    local baseScale = 1
    if screenHeight > 1080 then
        ---长宽高比例小于1.5的，被认为是pad类型
        if screenWidth / screenHeight < 1.5 then
            baseScale = 0.9
        else
            baseScale = 1080 / screenHeight
        end
    end

    local newScale = 720 / screenHeight
    universalRenderPipelineAsset.renderScale = newScale

    -- win 不设置
    -- if Application.platform == RuntimePlatform.WindowsPlayer then 

    -- else
    --     universalRenderPipelineAsset.renderScale = scale * baseScale
    -- end
end

---SetDynamicResolution
---只处理和ios的型吃，android的未处理
---设置场景的动态分辨率
function MobileHardwareUtils.SetDynamicResolution(scale)
    local deviceModel = SystemInfo.deviceModel
    if string.isEmpty(deviceModel) then
        ---设置为1
        MobileHardwareUtils.SetDRSScale(checkNumber(scale))
        return
    end
    if deviceModel then
        if deviceModel == "iPhone10,3" or deviceModel == "iPhone10,6" or deviceModel == "iPhone11,6" then
            MobileHardwareUtils.SetDRSScale(0.96)
            return
        end
    end
    MobileHardwareUtils.SetDRSScale(checkNumber(scale))
end

---GetAndroidQuality
