    return MobileHardwareUtils.CheckAndroidGPU(SystemInfo.graphicsDeviceName)
end

---CheckAndroidGPU
---检测android的gpu信息来分档次
---@param gpuName string
function MobileHardwareUtils.CheckAndroidGPU(gpuName)
    if string.isEmpty(gpuName) then
        return GraphicQuality.Low ---安全起见，未能识别的设备，默认低
    end

    local ret_quality = GraphicQuality.Low
    xpcall(function()
        ---去除高通cpu名字中的(TM)字符
        gpuName = string.gsub(gpuName, "%(TM%) ", '')

        ---获取三星的gpu
        for w in string.gmatch(gpuName, ".+(Xclipse [0-9]+).+") do
            gpuName = string.trim(w)
        end

        --最多保留三个部分
        local gpuSubnames = string.split(gpuName, ' ')

        ---首先查表来确定设备型号
        ---@type TableML.TableFile
        local tableFile = SettingModule.Get(AndroidModel_Setting_Path)

        for i = #gpuSubnames, 1, -1 do
            local keyname = gpuSubnames[1]
            for j = 2, i do
                keyname = keyname .. ' ' .. gpuSubnames[j]
            end

            ---@type TableML.TableFileRow
            local row = tableFile:GetByPrimaryKey(keyname, false)
            if not isNull(row) then
                local quality = checkNumber(row:Get("quality"))
                ret_quality = quality
                break
            end
        end

        ---以下为原来默认配置逻辑
        gpuName = string.lower(gpuName)
        local separators = { '\t', '\r', '\n', '+', '-', ':' }
        for i = 1, #separators do
            gpuName = string.gsub(gpuName, separators[i], ' ')
        end
        local tokens = string.split(gpuName, ' ')
        if not tokens or #tokens == 0 then
            printError("CheckAndroidGPU: Split gpu name fail")
            ret_quality = GraphicQuality.Low
        end
        --Adreno 308
        local vendor = tokens[1]
        local model
        if #tokens >= 2 then
            model = tokens[2]
        end
        local cpuName = SystemInfo.processorType
        local deviceModel = SystemInfo.deviceModel
        if not string.isEmpty(deviceModel) then
            deviceModel = string.lower(deviceModel)
        end
        ---检测模拟器
        if string.match(gpuName, "direct3d") or string.match(gpuName, "geforce") or string.match(gpuName, "gtx")
                or string.match(cpuName, "intel") or string.match(cpuName, "amd") or string.match(cpuName, "intel")
                or string.match(gpuName, "mumu") or string.match(gpuName, "nvidia") or string.match(deviceModel, "mumu") then
            ret_quality = GraphicQuality.Highest
        end
        --检查手机
        -- if string.match(vendor, "vivante") then
        --     return GraphicQuality.Middle
        -- elseif vendor == "adreno" then
        --     return MobileHardwareUtils.CheckAdrenoGPU(tokens)
        -- elseif vendor == "powervr" or vendor == "imagination" or vendor == "sgx" or vendor == "rogue" then
        --     return MobileHardwareUtils.CheckPowerVRGPU(tokens)
        -- elseif vendor == "arm" or vendor == "mali" or (#tokens > 1 and model and model == "mali") then
        --     return MobileHardwareUtils.CheckMaliGPU(tokens)
        -- elseif vendor == "tegra" then
        --     return MobileHardwareUtils.CheckTegraGPU(tokens)
        -- end
    end, function(err)
        --安全起见，未能识别的设备，默认低
        ret_quality = GraphicQuality.Low
    end)
    --安全起见，未能识别的设备，默认低
    return ret_quality
end

---CheckAdrenoGPU
---https://zh.wikipedia.org/wiki/Adreno
---检测高通型号gpu
---@param tokens table
function MobileHardwareUtils.CheckAdrenoGPU(tokens)
    local seriesNum = 0
    for i = 1, #tokens do
        seriesNum = tonumber(tokens[i])
        if seriesNum then

            --- 17年的芯片，游戏跑不到高配了
            --if seriesNum == 540 then
            --    --835
            --    return GraphicQuality.High
            --end

            if seriesNum == 618 then
                --855+
                return GraphicQuality.High
            end

            if seriesNum == 616 then
                --710
                return GraphicQuality.High
            end

            if seriesNum < 400 then
                return GraphicQuality.Lowest
            elseif seriesNum <= 509 then
                return GraphicQuality.Lowest
                --- 510系列归来低档位
            elseif seriesNum <= 510  then
                return GraphicQuality.Low
            elseif seriesNum < 600 then
                return GraphicQuality.Middle
            else

                if seriesNum >= 600 and seriesNum < 700 then

                    if seriesNum <= 627 then
                        --616
                        return GraphicQuality.Middle
                    else
                        -- if seriesNum >= 640 then
                        --     --640
                        --     return GraphicQuality.Highest
                        -- else
                            --630
                            return GraphicQuality.High
                        -- end

                    end
                ---未出的型号
                elseif seriesNum >= 700 and seriesNum < 800 then
                    --700系列都是高端
                    -- return GraphicQuality.Highest
                    return GraphicQuality.High

                else
                    --800
                    if seriesNum <= 900 then

                        -- if seriesNum <= 806 then
                        --     --800 ~ 806
                        --     return GraphicQuality.Highest
                        -- else

                        --     if seriesNum >= 820 then
                        --         --820以上为最高端
                        --         return GraphicQuality.Highest
                        --     else
                        --         --806~820
                        --         return GraphicQuality.Highest
                        --     end

                        -- end
                        return GraphicQuality.High
                    else
                        --未知系列默认返回高端机
                        return GraphicQuality.Middle
                    end

                    --默认返回中端机
                    return GraphicQuality.Middle
                end

            end
        end
    end
    return GraphicQuality.Middle
end

---CheckPowerVRGPU
---Imagination公司PowerVR系列的移动GPU
---@param tokens table
function MobileHardwareUtils.CheckPowerVRGPU(tokens)
    for i = 1, #tokens do
        local token = tokens[i]
        if token == "sgx" then
            return GraphicQuality.Lowest
        end

        if token == "furian" then
            return GraphicQuality.Lowest
        end

        local char1 = string.byte(token, 1)
        local gByte = string.byte('g', 1)
        local isGSeries = char1 == gByte
        if not isGSeries then
            return GraphicQuality.Low
        end

        -- Getting series number
        local seriesNum = -1
        local char2 = string.byte(token, 2)
        local isNumberStartAt2 = char2 >= string.byte('0', 1) and char2 <= string.byte('9', 1)
        if isNumberStartAt2 then
            seriesNum = tonumber(string.sub(token, 2))
        else
            seriesNum = tonumber(string.sub(token, 1))
        end

        if not seriesNum then
            return GraphicQuality.Low
        end
        -- Return by series number
        if seriesNum > 0 then
            if seriesNum >= 9400 then
                return GraphicQuality.Middle
            elseif seriesNum >= 8300 then
                return GraphicQuality.Low
            else -- redmi 6 GE8320 Huawei Y5 2018 GE8100
                return GraphicQuality.Lowest
            end
        end
    end
    return GraphicQuality.Lowest
end

---CheckMaliGPU
---Arm系列gpu
---@param tokens table
function MobileHardwareUtils.CheckMaliGPU(tokens)
    -- Format : arm mali 'g/t'number
    for i = 2, #tokens do
        local token = tokens[i]
        -- Getting flags
        local firstCharByte = string.byte(token, 1)
        local tByte = string.byte('t', 1)
        local gByte = string.byte('g', 1)
        local tFlag = firstCharByte == tByte
        local gFlag = firstCharByte == gByte
        local flag = tFlag or gFlag

        -- Getting series number
        local seriesNum = MobileHardwareUtils._GetMaliSeriesNumByToken(token, flag)
        if not isNull(seriesNum) then
            -- Getting quality
            local quality = MobileHardwareUtils._GetQualityByMaliSeriesNum(seriesNum, gFlag, tFlag)
            if quality then
                return quality
            end
        end
    end

    return GraphicQuality.Middle
end

---GetMaliSeriesNumByToken
---获取mali gpu的序列号
---@param token string
---@param flag boolean
function MobileHardwareUtils._GetMaliSeriesNumByToken(token, flag)
     --local tag = "MobileHardwareUtils._GetMaliSeriesNumByToken"
     --print(tag .. "token = " .. token .. ", flag = " .. tostring(flag))
    local mpIndex = string.last_index_of(token, "mp")
    if mpIndex > 1 then
         --print(tag .. "mpIndex > 1")
        -- 't/g' + number + mp
        local startIndex = 1
        if flag then
            startIndex = 2
        else
            startIndex = 1
        end
        token = string.sub(token, startIndex, mpIndex - startIndex)
         --print(tag .. "token = " .. token)
    else
        -- 't/g' + number
        if flag then
            token = string.sub(token, 2)
        end
         --print(tag .. "token = " .. token)
    end

    local result = tonumber(token)
    return result
end

function MobileHardwareUtils._GetQualityByMaliSeriesNum(seriesNum, gFlag, tFlag)
     --local tag = "MobileHardwareUtils._GetQualityByMaliSeriesNum : "
     --print("mali series number = " .. seriesNum)

    if seriesNum <= 0 then
        return GraphicQuality.Middle
    end

    -- G series
    if gFlag then
         --print("Mali G series " .. seriesNum)
        if seriesNum >= 76 then
             --print("seriesNum >= 76")
            return GraphicQuality.High
        elseif seriesNum >= 72 then -- MP value
             --print("seriesNum >= 72")
            --G72
            return GraphicQuality.Middle
        elseif seriesNum >= 71 then -- MP value
            return GraphicQuality.Middle
        elseif seriesNum >= 52 then
            --kirin 810
            return GraphicQuality.High
        else -- huawei Lite G51 G71
            return GraphicQuality.Middle
        end
    end

    -- T series Opengl ES 3.1
    if tFlag then
         --print("Mali T series " .. seriesNum)
        if seriesNum >= 780 then -- MTK MP NightMare
            return GraphicQuality.Middle
        else -- 720 760
            return GraphicQuality.Low
        end
    end

    -- Other series
    if seriesNum < 600 and seriesNum >= 200 then
         --print("seriesNum < 600 and seriesNum >= 200")
        return GraphicQuality.Low
    else
         --print(tag .. "else")
        return GraphicQuality.Middle
    end
end


---CheckTegraGPU
---Tegra型号gpu
---@param tokens table
function MobileHardwareUtils.CheckTegraGPU(tokens)
    for i = 1, #tokens do
        local text = tokens[i]
        if text == "k1" then
            return GraphicQuality.Lowest
        end
        if text == "x1" then
            return GraphicQuality.Low
        end
    end
    return GraphicQuality.Middle
end

return MobileHardwareUtils